CREATE TABLE stock_container(id TEXT PRIMARY KEY CHECK(length(id)>0),person TEXT NOT NULL,item TEXT NOT NULL,label TEXT NOT NULL CHECK(length(label) BETWEEN 1 AND 500),unit TEXT NOT NULL CHECK(unit IN ('mg','ml','count')),strength TEXT NOT NULL,revision INTEGER NOT NULL CHECK(revision>0),sequence INTEGER NOT NULL CHECK(sequence>=0),measurement_sequence INTEGER NOT NULL CHECK(measurement_sequence>=0 AND measurement_sequence<=sequence),balance_status TEXT NOT NULL CHECK(balance_status IN ('known','unknown','limit')),numerator TEXT,denominator TEXT,threshold_n TEXT,threshold_d TEXT,refill INTEGER NOT NULL CHECK(refill IN (0,1)),notice_eligible INTEGER NOT NULL DEFAULT 0 CHECK(notice_eligible IN (0,1)),notice_active INTEGER NOT NULL DEFAULT 1 CHECK(notice_active IN (0,1)), product_label TEXT,UNIQUE(id,person),UNIQUE(id,person,item),FOREIGN KEY(item,person) REFERENCES item(id,person),CHECK((numerator IS NULL)=(denominator IS NULL)),CHECK((balance_status='known')=(numerator IS NOT NULL)),CHECK((threshold_n IS NULL)=(threshold_d IS NULL)),CHECK(numerator IS NULL OR (length(numerator) BETWEEN 1 AND 20000 AND length(denominator) BETWEEN 1 AND 20000))) STRICT;
CREATE TABLE stock_movement(id TEXT PRIMARY KEY CHECK(length(id)>0),person TEXT NOT NULL,container TEXT NOT NULL,sequence INTEGER NOT NULL CHECK(sequence>0),kind TEXT NOT NULL CHECK(kind IN ('restock','actualUse','waste','reconciliation','correction')),numerator TEXT,denominator TEXT,strength TEXT NOT NULL,entered TEXT,entered_unit TEXT CHECK(entered_unit IN ('mg','ml','count')),record TEXT UNIQUE,reverses TEXT UNIQUE,physical_choice TEXT CHECK(physical_choice IN ('reverseRecordedEffect','retainPhysicalEffect')),replacement TEXT,reason TEXT CHECK(length(reason)<=4000),operation TEXT NOT NULL UNIQUE CHECK(length(operation)>0),generation TEXT NOT NULL CHECK(length(generation)>0),recorded_at INTEGER NOT NULL,UNIQUE(container,sequence),UNIQUE(id,person,container),FOREIGN KEY(container,person) REFERENCES stock_container(id,person) ON DELETE CASCADE,FOREIGN KEY(record,person) REFERENCES administration(id,person),FOREIGN KEY(reverses,person,container) REFERENCES stock_movement(id,person,container),CHECK((numerator IS NULL)=(denominator IS NULL)),CHECK((kind='actualUse')=(record IS NOT NULL)),CHECK((kind='correction')=(reverses IS NOT NULL)),CHECK((kind='correction')=(physical_choice IS NOT NULL)),CHECK((entered IS NULL)=(entered_unit IS NULL)),CHECK(numerator IS NULL OR (length(numerator) BETWEEN 1 AND 20000 AND length(denominator) BETWEEN 1 AND 20000))) STRICT;
CREATE TABLE supporting_context(record TEXT NOT NULL,person TEXT NOT NULL,revision INTEGER NOT NULL,item TEXT,event TEXT,CHECK((item IS NOT NULL)+(event IS NOT NULL)=1),FOREIGN KEY(record,person,revision) REFERENCES supporting_revision(record,person,revision) ON DELETE CASCADE,FOREIGN KEY(item,person) REFERENCES item(id,person),FOREIGN KEY(event,person) REFERENCES event_record(id,person)) STRICT;
CREATE TABLE supporting_metric(id TEXT PRIMARY KEY,person TEXT NOT NULL REFERENCES person(id),kind TEXT NOT NULL CHECK(kind IN ('lab','observation')),name TEXT NOT NULL,revision INTEGER NOT NULL CHECK(revision>0),UNIQUE(id,person)) STRICT;
INSERT INTO "supporting_metric" VALUES ('v19-metric','me','lab','Synthetic marker',1);
CREATE TABLE supporting_record(id TEXT PRIMARY KEY,person TEXT NOT NULL REFERENCES person(id),kind TEXT NOT NULL CHECK(kind IN ('labPanel','observation')),revision INTEGER NOT NULL CHECK(revision>0),entered_at INTEGER NOT NULL,entry_day TEXT NOT NULL,voided INTEGER NOT NULL CHECK(voided IN (0,1)),collection_day TEXT,collection_at INTEGER,report_day TEXT,report_at INTEGER,UNIQUE(id,person),FOREIGN KEY(id,person,revision) REFERENCES supporting_revision(record,person,revision) DEFERRABLE INITIALLY DEFERRED) STRICT;
